tool_calls.command:
cd /home/kara/speclang && cat > /tmp/mcp_probe.mjs <<'EOF'
import { MCPServer } from './dist/mcp/server.js';
import { mkdtempSync } from 'fs';
import { tmpdir } from 'os';
import { join } from 'path';

const dir = mkdtempSync(join(tmpdir(), 'mcp-probe-'));
const dbPath = join(dir, 'fresh.db');
const server = new MCPServer({ port: 3999, database: dbPath, specsDir: 'specs' });
await server.startHTTP(3999);
await new Promise(r => setTimeout(r, 500));
const res = await fetch('http://localhost:3999/mcp/message', {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: JSON.stringify({ jsonrpc: '2.0', id: 1, method: 'tools/call', params: { name: 'speclang_cascade_status', arguments: {} } })
});
console.log('HTTP_STATUS', res.status);
console.log('BODY', JSON.stringify(await res.json()));
await server.stop();
process.exit(0);
EOF
ls dist/mcp/server.js && node /tmp/mcp_probe.mjs 2>&1 | tail -20
